/**  One thing an agent did, as verb, object and outcome: "edited", "src/main.rs", "+3 -1". */
export type Activity = {
	/**  The agent's own id for it, so a later report can update it. */
	id: string,
	/**  What it did. */
	verb: string,
	/**  What to. */
	object: string,
	/**  How it went, once known. */
	outcome?: string | null,
	/**  What it printed or read, shown to everyone in the chat. */
	output?: string | null,
};

/**  One agent found. */
export type AgentInfo = {
	/**  Which. */
	kind: AgentKind,
	/**  Where. */
	runs_in: RunsIn,
	/**  Whether it is the one that runs there. */
	chosen: boolean,
};

/**  The agents Player Two knows how to start over ACP, in the order it prefers them. */
export type AgentKind = 
/**  Cursor's command line, `agent acp`. */
"cursor" | 
/**  GitHub Copilot's command line, `copilot --acp --stdio`. */
"copilot" | 
/**  Claude Code, through its ACP adapter. */
"claude";

/**  One channel, as `GET /channels` lists it. */
export type ChannelInfo = {
	/**  Its name, without the `#`. */
	name: ChannelName,
	/**  Who is in it. */
	members: PersonName[],
};

/**  A channel's name, without its `#`: 1 to 32 lowercase letters, digits or `-`. */
export type ChannelName = string;

/**
 *  A chat: a channel, written `#name`, or a direct chat between two people, written with their
 *  names in sorted order joined by `+`.
 */
export type ChatId = string;

/**  One line of the chat list. */
export type ChatSummary = {
	/**  The chat. */
	chat: ChatId,
	/**  What to call it: `#name`, or the other person's name. */
	title: string,
	/**  Messages from others since the person last read it. */
	unread: number,
	/**  For a direct chat, whether the other person is here. */
	here: boolean | null,
};

/**  One chat, or one thread of it. */
export type ChatView = {
	/**  The chat. */
	chat: ChatId,
	/**  What to call it. */
	title: string,
	/**  Who is in it. */
	members: PersonName[],
	/**
	 *  For a direct chat, the other person: whether they are here, when they were last, and
	 *  what they share.
	 */
	person: Person | null,
	/**  The thread shown, by its first message, or none for the top level. */
	thread: number | null,
	/**  Its messages, oldest first. */
	items: Item[],
	/**  Whether the hub has older events than these. */
	has_older: boolean,
	/**  The first message the person has not read, if any. */
	first_unread: number | null,
};

/**  How the desk stands with the hub. */
export type Connection = 
/**  This machine has not joined a hub. */
{ state: "not_joined" } | 
/**  Connecting, or loading what is there. */
{ state: "connecting" } | 
/**  Up to date, and hearing new events as they come. */
{ state: "connected" } | 
/**  Not connected; trying again. */
{ state: "offline"; 
/**  Why, in words. */
reason: string } | 
/**  The hub runs another version, so the app must change before anything else. */
{ state: "wrong_version"; 
/**  The hub's version. */
hub: string };

/**  Something the desk tells the window without being asked: what to ask for again. */
export type Event = 
/**  The overview changed. */
{ type: "overview" } | 
/**  A chat changed. */
{ type: "chat"; 
/**  Which. */
chat: ChatId } | 
/**
 *  Something worth a notification arrived: a direct message, a tag of the person or their
 *  places, a follow-up waiting for their click, or the end of a run they asked for. The app
 *  shows it while the window is not in front.
 */
{ type: "notify"; 
/**  Where. */
chat: ChatId; 
/**  The thread it is in, if any. */
thread: number | null; 
/**  Who, and where. */
title: string; 
/**  The start of what they said. */
body: string } | 
/**  The person clicked a notification: the window opens its chat, and its thread. */
{ type: "open"; 
/**  Which. */
chat: ChatId; 
/**  The thread, if any. */
thread: number | null } | 
/**  The person chose Settings in the tray's menu: the window opens it. */
{ type: "settings" };

/**  One message as the window draws it. */
export type Item = {
	/**  Its id. */
	id: number,
	/**  Who wrote it. */
	author: PersonName,
	/**  When, in Unix milliseconds. */
	ts: number,
	/**  What it says. The window draws it as text. */
	text: string,
	/**  The places it tags. */
	tags: Tag[],
	/**  How many replies its thread has. */
	replies: number,
	/**  The runs that answer it. */
	runs: RunView[],
	/**  The tags of it nobody has answered yet: not run, declined or taken back. */
	waiting: Tag[],
	/**
	 *  For a follow-up nobody has answered yet, the run it follows: its owner decides whether it
	 *  runs, with that run's settings.
	 */
	follows: RunView | null,
	/**  Lines for the `@` mentions in it that name nobody, or a place not shared. */
	unknown: string[],
};

/**  The chat list, the people and how the connection stands. */
export type Overview = {
	/**  Who this machine joined as. */
	me: PersonName | null,
	/**  How the desk stands with the hub. */
	connection: Connection,
	/**  The chats to list: the person's channels, then a direct chat with everyone else. */
	chats: ChatSummary[],
	/**  Everyone who has joined. */
	people: Person[],
	/**  Every channel, joined or not. */
	channels: ChannelInfo[],
	/**  The person's places with a run going now. */
	busy: PlaceName[],
};

/**  One person, as `GET /people` lists them. */
export type Person = {
	/**  Their name. */
	name: PersonName,
	/**  Whether they have a stream open now. */
	here: boolean,
	/**  When their last stream closed, in Unix milliseconds. */
	last_seen?: number | null,
	/**  The places their desk advertises. */
	places: PlaceInfo[],
};

/**  A person's name on the hub: a lowercase letter, then up to 31 lowercase letters, digits or `-`. */
export type PersonName = string;

/**  A place as the hub lists it: its name and kind, and nothing about where it is. */
export type PlaceInfo = {
	/**  Its name. */
	name: PlaceName,
	/**  Machine or folder. */
	kind: PlaceKind,
};

/**  Whether a place is a machine or a shared folder. */
export type PlaceKind = 
/**  The person's machine. */
"machine" | 
/**  One of their shared folders. The wire calls it `repo`. */
"repo";

/**
 *  Where an agent can run for someone: `machine`, or one of their shared folders, named by up
 *  to 64 lowercase letters, digits, `.`, `_` or `-`, starting with a letter or digit.
 */
export type PlaceName = string;

/**  The person's places. */
export type PlacesView = {
	/**  Where `@me` runs by default. */
	machine_runs_in: RunsIn,
	/**  The folders shared. */
	folders: SharedFolder[],
	/**  The WSL distros with an agent in them; none without WSL, or with no agent in it. */
	distros: string[],
	/**  The agents found, and where. */
	agents: AgentInfo[],
	/**
	 *  Agents installed in part on Windows: the Cursor editor without its agent, or Claude Code
	 *  without its ACP adapter.
	 */
	half_installed: AgentKind[],
	/**
	 *  Whether there is a WSL distro, not counting Docker Desktop's, where an agent could be
	 *  installed.
	 */
	wsl: boolean,
};

/**  Something the window asks of the desk. */
