/**  The desk's answer to one [`Request`]. */
export type Response = 
/**  The answer to [`Request::Hello`]. */
({ type: "hello"; 
/**  The version the hub, the app and the desk all share. */
version: string }) & { choices?: never; dirty?: never; joined?: never; message?: never; ok?: never; output?: never; ready?: never; runs_in?: never; sign_in?: never; suggested_name?: never } | 
/**  The answer to [`Request::Setup`]. */
({ type: "setup"; 
/**  The name this machine joined under, once it has. */
joined: PersonName | null; 
/**  The name to offer, from the Windows user name. */
suggested_name: string | null }) & { choices?: never; dirty?: never; message?: never; ok?: never; output?: never; ready?: never; runs_in?: never; sign_in?: never; version?: never } | 
/**  The answer to [`Request::Overview`]. */
{
	type: "overview",
} & Overview | 
/**  The answer to [`Request::Chat`]. */
{
	type: "chat",
} & ChatView | 
/**  The answer to [`Request::Places`]. */
{
	type: "places",
} & PlacesView | 
/**  The answer to [`Request::Approval`]. */
({ type: "approval"; 
/**  Where it may run: Windows, or a WSL distro with an agent in it. */
choices: RunsIn[]; 
/**  Where it runs unless the owner picks another. */
runs_in: RunsIn; 
/**  Whether a git checkout has changes not committed, which an edit would run among. */
dirty: boolean }) & { joined?: never; message?: never; ok?: never; output?: never; ready?: never; sign_in?: never; suggested_name?: never; version?: never } | 
/**  The answer to [`Request::InstallCursor`]. */
({ type: "installed"; 
/**  Whether the installer said it succeeded. */
ok: boolean; 
/**  The end of what it printed. */
output: string }) & { choices?: never; dirty?: never; joined?: never; message?: never; ready?: never; runs_in?: never; sign_in?: never; suggested_name?: never; version?: never } | 
/**  The answer to [`Request::CheckAgent`] and [`Request::SignIn`]. */
({ type: "checked"; 
/**  Whether the agent opened a session. */
ready: boolean; 
/**  What was found, in words. */
message: string; 
/**  Whether the agent says it must be signed in, so that Sign in is offered. */
sign_in: boolean }) & { choices?: never; dirty?: never; joined?: never; ok?: never; output?: never; runs_in?: never; suggested_name?: never; version?: never } | 
/**  The request was done, and there is nothing more to say. */
({ type: "done" }) & { choices?: never; dirty?: never; joined?: never; message?: never; ok?: never; output?: never; ready?: never; runs_in?: never; sign_in?: never; suggested_name?: never; version?: never };

/**  How a run stands. */
export type RunState = 
/**  It is going on. */
"working" | 
/**  It finished. */
"done" | 
/**  Its owner, or its asker, stopped it. */
"stopped" | 
/**  It failed. */
"failed";

/**  One run, as the window draws it under the message it answers. */
export type RunView = {
	/**  The run, by its `run.accepted`. */
	id: number,
	/**  The thread its events are in. */
	thread: number,
	/**  Whose machine it runs on. */
	owner: PersonName,
	/**  Which place. */
	place: PlaceName,
	/**  Where on the machine. */
	runs_in: RunsIn,
	/**  Whether its asker's follow-ups run without a new click. */
	keep_going: boolean,
	/**  How it stands. */
	state: RunState,
	/**  Why it failed or was stopped, when it says. */
	reason: string | null,
	/**  What it did, each item as it now stands, in the order they began. */
	activity: Activity[],
	/**  The agent's answer, as Markdown. */
	result: string | null,
	/**  Whether this person may stop it: its owner, or its asker. */
	may_stop: boolean,
	/**  Whether the run is this machine's, so this person may stop it. */
	mine: boolean,
};

/**  Where on a machine a run happens: `windows`, or `wsl:<distro>`. */
export type RunsIn = string;

/**  One shared folder, as the settings page shows it. */
export type SharedFolder = {
	/**  The name it is tagged by. */
	name: PlaceName,
	/**  Where it is, as a Windows path, or a Linux one inside its distro. */
	path: string,
	/**  Which system it is on. */
	runs_in: RunsIn,
	/**  Why it cannot run now, when it cannot. It is not advertised until it can. */
	unavailable: string | null,
};

/**  One tag in a message: `@person` or `@person/place`. */
export type Tag = {
	/**  Whose place. */
	person: PersonName,
	/**  Which place: `machine` for `@person`. */
	place: PlaceName,
};
